contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address logger, address keepAddr, bytes32 digest) public {
        // On a fresh deployment the owner is unset, so attempts to grant
        // logger approval must revert, for any caller and any arguments.
        bool setReverted;
        c.setApprovedLogger(logger, true); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            setReverted = true;
        } else {
            setReverted = false;
        }

        bool approvedNew = c.approvedToLog(logger); if (__ESBMC_reverted()) return;
        bool approvedSelf = c.approvedToLog(address(this)); if (__ESBMC_reverted()) return;

        bool r1 = c.logCreated(keepAddr); if (__ESBMC_reverted()) return;
        bool r2 = c.logSetupFailed(); if (__ESBMC_reverted()) return;
        bool r3 = c.logLiquidated(); if (__ESBMC_reverted()) return;
        bool r4 = c.logRedeemed(digest); if (__ESBMC_reverted()) return;

        assert(setReverted && !approvedNew && !approvedSelf && !r1 && !r2 && !r3 && !r4);
    }
    receive() external payable {}
}

