    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DepositLog c;

    function setUp() public {
        c = new DepositLog();
    }

    function _run(address logger, address keepAddr, bytes32 digest) internal {
        bool setReverted;
        try c.setApprovedLogger(logger, true) {
            setReverted = false;
        } catch {
            setReverted = true;
        }
        bool approvedNew;
        try c.approvedToLog(logger) returns (bool __r) { approvedNew = __r; } catch { return; }
        bool approvedSelf;
        try c.approvedToLog(address(this)) returns (bool __r) { approvedSelf = __r; } catch { return; }
        bool r1;
        try c.logCreated(keepAddr) returns (bool __r) { r1 = __r; } catch { return; }
        bool r2;
        try c.logSetupFailed() returns (bool __r) { r2 = __r; } catch { return; }
        bool r3;
        try c.logLiquidated() returns (bool __r) { r3 = __r; } catch { return; }
        bool r4;
        try c.logRedeemed(digest) returns (bool __r) { r4 = __r; } catch { return; }
        assertTrue(setReverted && !approvedNew && !approvedSelf && !r1 && !r2 && !r3 && !r4);
    }

    function testFuzz_run(address logger, address keepAddr, bytes32 digest) public {
        vm.assume(logger.code.length == 0 && uint160(logger) > 0xffff && logger != address(this) && logger != address(c) && logger != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && logger != 0x000000000000000000636F6e736F6c652e6c6f67 && logger != 0x4e59b44847b379578588920cA78FbF26c0B4956C && logger != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(keepAddr.code.length == 0 && uint160(keepAddr) > 0xffff && keepAddr != address(this) && keepAddr != address(c) && keepAddr != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && keepAddr != 0x000000000000000000636F6e736F6c652e6c6f67 && keepAddr != 0x4e59b44847b379578588920cA78FbF26c0B4956C && keepAddr != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(logger, keepAddr, digest);
    }

    receive() external payable {}
}
